// ====== CONFIGURAÇÃO DOS ATENDIMENTOS (edite só este bloco) ======
const PAINEL_URL   = '__PAINEL_URL__';     // ingest do plugin GLPI (o mesmo do coletor de O.S.)
const PAINEL_TOKEN = '__PAINEL_TOKEN__';
const FINALIZADOS_DIAS       = 3;          // rotina de hora em hora: finalizados com última alteração nos últimos N dias
const FINALIZADOS_DIAS_CARGA = 90;         // gatilho "Manual (carga finalizados 90 dias)": 1ª carga do histórico
const STATUS_FINALIZADO = 'S';             // su_ticket.su_status do atendimento finalizado (Solucionado)
const STATUS_FORA_ABERTOS = ['S', 'C'];    // "aberto" = su_status diferente destes (o IXC não aceita IN em status)
const LOTE = 400;                          // atendimentos por consulta de O.S. / clientes
const BASES = [                            // credencial de cada base fica nos nós "<etapa> <base>"
  { codigo: 'resolutto', nome: 'Resolutto', url: '__URL_RESOLUTTO__' },
  { codigo: '4btelecom', nome: '4BTELECOM', url: '__URL_4BTELECOM__' },
  { codigo: 'ponto',     nome: 'PONTO',     url: '__URL_PONTO__' },
  { codigo: 'cacta',     nome: 'CACTA',     url: '__URL_CACTA__' },
  { codigo: 'buzz',      nome: 'BUZZ',      url: '__URL_BUZZ__' },
];
// ============================================================
// MODO vem do gatilho: "...finalizados..." / "...carga..." = finalizados; os outros = abertos.
const gatilho = String($prevNode.name || '');
const MODO = /finalizados|carga/i.test(gatilho) ? 'finalizados' : 'abertos';
const DIAS = /carga/i.test(gatilho) ? FINALIZADOS_DIAS_CARGA : FINALIZADOS_DIAS;
return [{ json: { PAINEL_URL, PAINEL_TOKEN, MODO, DIAS, GATILHO: gatilho, STATUS_FINALIZADO, STATUS_FORA_ABERTOS, LOTE,
  BASES: BASES.map(b => ({ ...b, url: String(b.url || '').trim().replace(/\/+$/, '') })) } }];

const urlOk = (u) => /^https?:\/\/\S+$/i.test(u || '') && !/PREENCHER/i.test(u || '');
const filtroIds = (tb, ids) => {
  const v = [...new Set((ids || []).map(x => String(x)).filter(x => /^\d+$/.test(x) && x !== '0'))];
  if (!v.length) return { TB: tb, OP: '=', P: '0' };                 // nada a buscar: consulta vazia (mantém o fluxo)
  return v.length === 1 ? { TB: tb, OP: '=', P: v[0] } : { TB: tb, OP: 'IN', P: v.join(',') };
};
const corpo = (tab, grid, ordem) => ({ qtype: tab + '.id', query: '0', oper: '>', page: '1', rp: '5000',
  sortname: tab + '.id', sortorder: ordem || 'asc', grid_param: JSON.stringify(grid) });
const msgErro = (e) => typeof e === 'string' ? e : (e && (e.message || e.description)) || JSON.stringify(e);
const falhou = (r) => {
  if (!r) return 'sem resposta';
  if (r.error) return msgErro(r.error);
  if (r.type === 'error') return 'IXC recusou: ' + (r.message || JSON.stringify(r)).slice(0, 300);
  if (!Number.isFinite(Number(r.total))) return 'resposta inesperada (sem "total"): ' + JSON.stringify(r).slice(0, 200);
  if (Number(r.total) > 0 && !Array.isArray(r.registros)) return 'IXC informou ' + r.total + ' registros mas não mandou a lista';
  return '';
};
const regs = (r) => Array.isArray(r && r.registros) ? r.registros : [];
// Etapa 1: atendimentos (su_ticket) de cada base — abertos, ou finalizados com última alteração na janela.
const cfg = $input.first().json;
const desde = new Date(Date.now() - (Number(cfg.DIAS) || 3) * 86400000).toISOString().slice(0, 10) + ' 00:00:00';
const grid = cfg.MODO === 'finalizados'
  ? [{ TB: 'su_ticket.su_status', OP: '=', P: cfg.STATUS_FINALIZADO }, { TB: 'su_ticket.data_ultima_alteracao', OP: '>=', P: desde }]
  : cfg.STATUS_FORA_ABERTOS.map(s => ({ TB: 'su_ticket.su_status', OP: '!=', P: s }));
return cfg.BASES.map(b => {
  const ok = urlOk(b.url);
  return { json: { base: b.codigo, chave: 'atendimentos', url: ok ? b.url + '/webservice/v1/su_ticket' : '',
    corpo: corpo('su_ticket', grid, 'desc'), erro_config: ok ? '' : 'URL do IXC não preenchida no Config (' + b.nome + ')' } };
});

const msgErro = (e) => typeof e === 'string' ? e : (e && (e.message || e.description)) || JSON.stringify(e);
const lerIxc = (j) => {
  if (!j) return { error: 'sem resposta' };
  if (j.error) return { error: msgErro(j.error) };
  const raw = j.data;
  if (raw === undefined) return j;
  if (typeof raw !== 'string') return raw;
  const txt = raw.replace(/^﻿/, '').trim();
  try { return JSON.parse(txt); } catch (e) { /* tenta limpar */ }
  try { return JSON.parse(txt.replace(/[\u0000-\u001F]+/g, ' ')); } catch (e) {
    return { error: 'resposta do IXC não é JSON (' + txt.length + ' bytes): ' + txt.slice(0, 180) };
  }
};
// Devolve {base, chave, resp} (o item pareado em "Buscar atendimentos" diz de quem é).
const req = $('Buscar atendimentos').item.json;
const resp = req.erro_config ? { error: req.erro_config } : lerIxc($input.item.json || {});
return { json: { base: req.base, chave: req.chave, resp } };

const urlOk = (u) => /^https?:\/\/\S+$/i.test(u || '') && !/PREENCHER/i.test(u || '');
const filtroIds = (tb, ids) => {
  const v = [...new Set((ids || []).map(x => String(x)).filter(x => /^\d+$/.test(x) && x !== '0'))];
  if (!v.length) return { TB: tb, OP: '=', P: '0' };                 // nada a buscar: consulta vazia (mantém o fluxo)
  return v.length === 1 ? { TB: tb, OP: '=', P: v[0] } : { TB: tb, OP: 'IN', P: v.join(',') };
};
const corpo = (tab, grid, ordem) => ({ qtype: tab + '.id', query: '0', oper: '>', page: '1', rp: '5000',
  sortname: tab + '.id', sortorder: ordem || 'asc', grid_param: JSON.stringify(grid) });
const msgErro = (e) => typeof e === 'string' ? e : (e && (e.message || e.description)) || JSON.stringify(e);
const falhou = (r) => {
  if (!r) return 'sem resposta';
  if (r.error) return msgErro(r.error);
  if (r.type === 'error') return 'IXC recusou: ' + (r.message || JSON.stringify(r)).slice(0, 300);
  if (!Number.isFinite(Number(r.total))) return 'resposta inesperada (sem "total"): ' + JSON.stringify(r).slice(0, 200);
  if (Number(r.total) > 0 && !Array.isArray(r.registros)) return 'IXC informou ' + r.total + ' registros mas não mandou a lista';
  return '';
};
const regs = (r) => Array.isArray(r && r.registros) ? r.registros : [];
// Etapa 2: O.S. dos atendimentos (su_oss_chamado.id_ticket) e nome dos clientes, em lotes.
// O 1º item de cada base leva o contexto (atendimentos da etapa 1 ou o erro) para o "Montar retratos".
const cfg = $('Config').first().json;
const resp = {}; for (const it of $input.all()) resp[it.json.base] = it.json.resp;
const lotes = (lista, n) => { const v = [...new Set(lista.map(String).filter(x => /^\d+$/.test(x) && x !== '0'))], o = [];
  for (let i = 0; i < v.length; i += n) o.push(v.slice(i, i + n)); return o; };
const out = [];
for (const b of cfg.BASES) {
  const r = resp[b.codigo];
  const erro = falhou(r);
  const atds = erro ? [] : regs(r);
  const ok = urlOk(b.url);
  const ec = ok ? '' : 'URL do IXC não preenchida no Config (' + b.nome + ')';
  const ctx = { erro, total: erro ? null : Number(r.total), atendimentos: atds.map(t => ({
    id: t.id, protocolo: t.protocolo, su_status: t.su_status, status: t.status, id_assunto: t.id_assunto,
    titulo: String(t.titulo || '').slice(0, 255), id_ticket_setor: t.id_ticket_setor, setor: t.setor,
    id_responsavel_tecnico: t.id_responsavel_tecnico, id_cliente: t.id_cliente,
    data_criacao: t.data_criacao, data_abertura: t.data_abertura, data_ultima_alteracao: t.data_ultima_alteracao })) };
  const lt = lotes(atds.map(t => t.id), Number(cfg.LOTE) || 400);
  const lc = lotes(atds.map(t => t.id_cliente), Number(cfg.LOTE) || 400);
  const itens = [];
  (lt.length ? lt : [[]]).forEach(ids => itens.push({ base: b.codigo, chave: 'os', url: ok ? b.url + '/webservice/v1/su_oss_chamado' : '',
    corpo: corpo('su_oss_chamado', [filtroIds('su_oss_chamado.id_ticket', ids)]), erro_config: ec }));
  lc.forEach(ids => itens.push({ base: b.codigo, chave: 'clientes', url: ok ? b.url + '/webservice/v1/cliente' : '',
    corpo: corpo('cliente', [filtroIds('cliente.id', ids)]), erro_config: ec }));
  // P13-3 (20/10): nomes dos setores (departamentos) do ATENDIMENTO: su_ticket.id_ticket_setor aponta para su_ticket_setor,
  // que NÃO é a mesma tabela dos setores das O.S. (empresa_setor) — antes o painel trocava "Comercial" por "Financeiro".
  if (!erro) itens.push({ base: b.codigo, chave: 'setores', url: ok ? b.url + '/webservice/v1/su_ticket_setor' : '',
    corpo: { qtype: 'su_ticket_setor.id', query: '0', oper: '>', page: '1', rp: '1000', sortname: 'su_ticket_setor.id', sortorder: 'asc' }, erro_config: ec });
  itens[0].ctx = ctx;
  itens.forEach(j => out.push({ json: j }));
}
return out;

const msgErro = (e) => typeof e === 'string' ? e : (e && (e.message || e.description)) || JSON.stringify(e);
const lerIxc = (j) => {
  if (!j) return { error: 'sem resposta' };
  if (j.error) return { error: msgErro(j.error) };
  const raw = j.data;
  if (raw === undefined) return j;
  if (typeof raw !== 'string') return raw;
  const txt = raw.replace(/^﻿/, '').trim();
  try { return JSON.parse(txt); } catch (e) { /* tenta limpar */ }
  try { return JSON.parse(txt.replace(/[\u0000-\u001F]+/g, ' ')); } catch (e) {
    return { error: 'resposta do IXC não é JSON (' + txt.length + ' bytes): ' + txt.slice(0, 180) };
  }
};
// Devolve {base, chave, resp} (o item pareado em "Buscar O.S. e clientes" diz de quem é).
const req = $('Buscar O.S. e clientes').item.json;
const resp = req.erro_config ? { error: req.erro_config } : lerIxc($input.item.json || {});
return { json: { base: req.base, chave: req.chave, resp } };

const urlOk = (u) => /^https?:\/\/\S+$/i.test(u || '') && !/PREENCHER/i.test(u || '');
const filtroIds = (tb, ids) => {
  const v = [...new Set((ids || []).map(x => String(x)).filter(x => /^\d+$/.test(x) && x !== '0'))];
  if (!v.length) return { TB: tb, OP: '=', P: '0' };                 // nada a buscar: consulta vazia (mantém o fluxo)
  return v.length === 1 ? { TB: tb, OP: '=', P: v[0] } : { TB: tb, OP: 'IN', P: v.join(',') };
};
const corpo = (tab, grid, ordem) => ({ qtype: tab + '.id', query: '0', oper: '>', page: '1', rp: '5000',
  sortname: tab + '.id', sortorder: ordem || 'asc', grid_param: JSON.stringify(grid) });
const msgErro = (e) => typeof e === 'string' ? e : (e && (e.message || e.description)) || JSON.stringify(e);
const falhou = (r) => {
  if (!r) return 'sem resposta';
  if (r.error) return msgErro(r.error);
  if (r.type === 'error') return 'IXC recusou: ' + (r.message || JSON.stringify(r)).slice(0, 300);
  if (!Number.isFinite(Number(r.total))) return 'resposta inesperada (sem "total"): ' + JSON.stringify(r).slice(0, 200);
  if (Number(r.total) > 0 && !Array.isArray(r.registros)) return 'IXC informou ' + r.total + ' registros mas não mandou a lista';
  return '';
};
const regs = (r) => Array.isArray(r && r.registros) ? r.registros : [];
// Um retrato por base para o painel. Falha nos atendimentos ou nas O.S. = {base, tipo, modo, erro} (o painel não encerra nada).
// Falha só nos clientes (nome e condomínio) vira aviso.
const cfg = $('Config').first().json;
const ctxs = {}; for (const it of $('Buscar O.S. e clientes').all()) if (it.json.ctx) ctxs[it.json.base] = it.json.ctx;
const resp = {}; for (const it of $input.all()) ((resp[it.json.base] = resp[it.json.base] || {})[it.json.chave] = resp[it.json.base][it.json.chave] || []).push(it.json.resp);
const vazio = (d) => !d || String(d).startsWith('0000') ? '' : String(d);
const def = (...v) => { for (const x of v) if (x !== undefined && x !== null && x !== '') return x; return null; };
const out = [];
for (const b of cfg.BASES) {
  const c = ctxs[b.codigo] || { erro: 'sem resposta da etapa 1', atendimentos: [] };
  const r = resp[b.codigo] || {};
  let erro = c.erro ? 'atendimentos: ' + c.erro : '';
  const avisos = [];
  const osPor = {};
  if (!erro) for (const x of (r.os || [{ error: 'sem resposta' }])) {
    const e = falhou(x); if (e) { erro = 'O.S. dos atendimentos: ' + e; break; }
    if (Number(x.total) > regs(x).length) avisos.push('lista de O.S. incompleta (IXC informou ' + x.total + ', vieram ' + regs(x).length + ')');
    for (const o of regs(x)) (osPor[o.id_ticket] = osPor[o.id_ticket] || []).push({ id: o.id, protocolo: o.protocolo, id_assunto: o.id_assunto, status: o.status });
  }
  if (erro) { out.push({ json: { base: b.codigo, tipo: 'atendimentos', modo: cfg.MODO, erro: String(erro).slice(0, 900) } }); continue; }
  const cli = {};
  for (const x of (r.clientes || [])) {
    const e = falhou(x); if (e) { avisos.push('clientes (nome/condomínio) indisponíveis: ' + e); continue; }
    for (const k of regs(x)) cli[String(k.id)] = { nome: String(k.razao || k.fantasia || '').trim(), cond: k.id_condominio };
  }
  // P13-3 (20/10): nomes dos setores do atendimento (su_ticket_setor); falha só vira aviso (o painel mantém os nomes que já tinha)
  const setores = [];
  for (const x of (r.setores || [])) {
    const e = falhou(x); if (e) { avisos.push('setores do atendimento (su_ticket_setor) indisponíveis: ' + e); continue; }
    for (const s of regs(x)) if (Number(s.id) > 0) setores.push({ id: Number(s.id), setor: String(s.setor || s.descricao || s.nome || '').trim() });
  }
  const atendimentos = c.atendimentos.map(t => ({
    id: t.id, protocolo: t.protocolo, status: def(t.su_status, t.status), id_assunto: t.id_assunto, titulo: t.titulo,
    id_setor: def(t.id_ticket_setor, t.setor), id_responsavel: t.id_responsavel_tecnico, id_cliente: t.id_cliente,
    cliente: (cli[String(t.id_cliente)] || {}).nome || '', id_condominio: (cli[String(t.id_cliente)] || {}).cond || null, data_abertura: vazio(def(t.data_criacao, t.data_abertura)),
    ultima_atualizacao: vazio(t.data_ultima_alteracao), os: osPor[t.id] || [] }));
  out.push({ json: { base: b.codigo, tipo: 'atendimentos', modo: cfg.MODO, ixc_url: b.url, total: c.total, atendimentos, setores, avisos: [...new Set(avisos)].slice(0, 4) } });
}
return out;
